const fruits = ["apple", "banana", "cherry"];
console.log(fruits.length);
console.log(fruits[0]);
console.log(fruits[fruits.length - 1]);
console.log(fruits.at(-1));
console.log(fruits[3]);

fruits[1] = "blueberry";          // replace an element
console.log(fruits.join(", "));

const queue = ["Ada"];
queue.push("Grace");       // add to the end
queue.unshift("Linus");    // add to the start
console.log(queue.join(" -> "));

const served = queue.shift();   // remove from the start
const last = queue.pop();       // remove from the end
console.log(served);
console.log(last);
console.log(queue.join(" -> "));

const numbers = [4, 9, 16, 25];
console.log(numbers.includes(16));
console.log(numbers.indexOf(25));
console.log(numbers.indexOf(7));
console.log(numbers.find((n) => n > 10));
console.log(numbers.findIndex((n) => n > 10));
console.log(numbers.some((n) => n > 20));
console.log(numbers.every((n) => n > 20));

const prices = [5, 12, 8, 30];

const doubled = prices.map((p) => p * 2);
console.log(doubled.join(", "));

const cheap = prices.filter((p) => p < 10);
console.log(cheap.join(", "));

const total = prices.reduce((sum, p) => sum + p, 0);
console.log(total);

console.log(prices.join(", "));   // the original is untouched

const tasks = [
  { title: "Write lesson", done: true },
  { title: "Record video", done: false },
  { title: "Publish", done: false },
];

tasks.forEach((task, index) => {
  console.log(`${index + 1}. ${task.done ? "[x]" : "[ ]"} ${task.title}`);
});

const pending = tasks.filter((t) => !t.done).map((t) => t.title);
console.log(pending.join(" | "));

const scores = [10, 9, 1, 100];
console.log(scores.toSorted().join(", "));              // compared as strings!
console.log(scores.toSorted((a, b) => a - b).join(", "));
console.log(scores.join(", "));                          // original unchanged

const letters = ["a", "b", "c", "d", "e"];
console.log(letters.slice(1, 3).join(""));   // copy of index 1 and 2
letters.splice(1, 2);                          // remove 2 elements at index 1
console.log(letters.join(""));
console.log(letters.toReversed().join(""));

const copy = [...letters];                     // shallow copy with spread
copy.push("z");
console.log(letters.length);
